func init() {
	generateCmd.Flags().StringP(generateInputArg, "i", "", "path to tool definition file")
	generateCmd.Flags().StringP(generateOutputArg, "o", "", "destination of the generated code")
	generateCmd.Flags().StringSlice(generateOverwriteExcludeGroupsArg, []string{}, "Generated SDK file groups to preserve when overwrite is enabled: ci (generated workflows, actions, release and container build files), linters (lint, editor, pre-commit and qlty configuration), gomod (Go module and workspace files), cli (generated CLI source and configuration, excluding command implementations), cli-implementation (CLI command implementations.go files), readme (README.md), project (repository/project support files including pyproject.toml, CODEOWNERS, Dependabot files, contribution/security documentation and similar project support metadata), agent (agent.md, Copilot instructions and generated skill files), sdk (generated SDK implementation, interfaces, configuration, additional types, options and enum definitions).")
	generateCmd.Flags().BoolP(generateOverwriteEnabledArg, "a", false, "overwrite state files")
	generateCmd.Flags().StringSlice(generateOverwriteExcludeFilesArg, []string{}, "Exact basenames or output-relative paths to preserve in the generated SDK when overwrite is enabled. Both slash styles are accepted; absolute and escaping paths are rejected. Unmatched entries are ignored.")
	generateCmd.Flags().StringSlice(generateOverwriteOnlyGroupsArg, []string{}, "Generate only files in the selected groups when overwrite is enabled. Uses the same group definitions as exclude-groups: ci, linters, gomod, cli, cli-implementation, readme, project, agent and sdk. Combines with only-files to select additional files; exclusions take precedence. Unmatched entries are ignored, and no files are generated if nothing matches. Supporting files must also be selected. If neither only option contains values, generation is unrestricted.")
	generateCmd.Flags().StringSlice(generateOverwriteOnlyFilesArg, []string{}, "Generate only exact basenames or output-relative paths when overwrite is enabled. Both slash styles are accepted; absolute and escaping paths are rejected. Combines with only-groups to select additional files; exclusions take precedence. Unmatched entries are ignored, and no files are generated if nothing matches. Supporting files must also be selected. If neither only option contains values, generation is unrestricted.")
	generateCmd.Flags().String(generateSummaryArg, "", "Write a human-readable summary to the selected destination. Allowed values: file, github, output, none.")
	generateCmd.Flags().String(generateSummaryFileArg, "", "Path to the summary file when summary is set to file")
	generateCmd.Flags().StringP(generateTargetedGoArg, "g", "", "targeted go version for the tool")
	agentCmd.Flags().Bool(agentInitArg, false, "install the embedded skills into the current repository")

	_ = configUtils.BindFlagToEnv(viperSession, config.App, "go_version", generateCmd.Flags().Lookup(generateTargetedGoArg))
	_ = configUtils.BindFlagToEnv(viperSession, config.App, "init", agentCmd.Flags().Lookup(agentInitArg))
	_ = configUtils.BindFlagToEnv(viperSession, config.App, "input", generateCmd.Flags().Lookup(generateInputArg))
	_ = configUtils.BindFlagToEnv(viperSession, config.App, "output", generateCmd.Flags().Lookup(generateOutputArg))
	_ = configUtils.BindFlagToEnv(viperSession, config.App, "overwrite_enabled", generateCmd.Flags().Lookup(generateOverwriteEnabledArg))
	_ = configUtils.BindFlagToEnv(viperSession, config.App, "overwrite_exclude_files", generateCmd.Flags().Lookup(generateOverwriteExcludeFilesArg))
	_ = configUtils.BindFlagToEnv(viperSession, config.App, "overwrite_exclude_groups", generateCmd.Flags().Lookup(generateOverwriteExcludeGroupsArg))
	_ = configUtils.BindFlagToEnv(viperSession, config.App, "overwrite_only_files", generateCmd.Flags().Lookup(generateOverwriteOnlyFilesArg))
	_ = configUtils.BindFlagToEnv(viperSession, config.App, "overwrite_only_groups", generateCmd.Flags().Lookup(generateOverwriteOnlyGroupsArg))
	_ = configUtils.BindFlagToEnv(viperSession, config.App, "summary", generateCmd.Flags().Lookup(generateSummaryArg))
	_ = configUtils.BindFlagToEnv(viperSession, config.App, "summary_file", generateCmd.Flags().Lookup(generateSummaryFileArg))

	rootCmd.AddCommand(generateCmd)
	rootCmd.AddCommand(schemaCmd)
	rootCmd.AddCommand(agentCmd)
}
